insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-refilled-cytokine-effector-plus', 'Refilled Hair Recovery Cytokine Effector Plus (Spot Serum)', 'Refilled', 'hair', 'physical', 'A small Korean roll-on scalp serum (0.51 fl oz, 15 ml) with a stainless steel roller, meant for spot use on the hairline, part, crown or brows. Refilled builds it around cADPR (cyclic adenosine diphosphate ribose), which it calls patented technology, plus salicylic acid, menthol, biotin and botanical extracts. Refilled says to use it 2 to 4 times a day without rinsing. It is sold as a cosmetic.', '$27.99 for 0.51 fl oz (15 ml) on Amazon; $29.00 at Ulta', 'https://m.media-amazon.com/images/I/61AgTzHlPLL._AC_SL500_.jpg', 'https://www.amazon.com/dp/B0GMRT3ZLD', '["refilled","effector plus","cadpr","cytokine","hair","scalp","hair serum","thinning","hairline","edges","roll-on","korean","cosmetic"]'::jsonb, '["skin-hair"]'::jsonb, '["Amazon","Ulta"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Sold as a cosmetic; not an FDA-approved drug for hair loss.","materials":"0.51 fl oz (15 ml) glass roll-on bottle with a stainless steel roller. The second ingredient is denatured alcohol, and it contains salicylic acid, menthol, added fragrance, limonene and linalool. Amazon says it is non-returnable and shipped as a hazardous material.","recalls":"No recalls found.","sideEffects":"Per Refilled''s Amazon safety information: external use only; stop if rash or irritation occurs when the skin is exposed to direct sunlight and see a doctor if it continues; don''t apply on wounds; rinse right away if it gets in your eyes. Ulta adds: stop if you get excessive discomfort or irritation, and don''t use on damaged or broken skin.","opinionAlerts":"Refilled''s results (89.90% less hair fall in concentrated areas, 11.65% less scalp redness and irritation, visible improvement after 2 weeks) are described only as \"clinical testing with dermatologist supervision,\" with no details on how many people took part or whether there was a comparison group. No published research on cADPR for hair was found."}'::jsonb, 'Refilled says, based on clinical testing with dermatologist supervision, that this serum reduced hair fall along the hairline, crown and part by 89.90%, reduced scalp redness and irritation by 11.65%, and visibly improved problem areas after 2 weeks. It doesn''t say how many people were tested, for how long, or whether there was a comparison group, and no published study of this product was found.

The ingredient Refilled builds the product around, cADPR (cyclic adenosine diphosphate ribose), has no published hair research that ayna could find: a PubMed search for it with hair returned one unrelated study. The listing also says the serum contains cytokines and NAD+, but neither appears by name in the full ingredient list on Ulta. Biotin is a common hair ingredient, but a 2017 review found evidence for it only in people with a deficiency or specific hair and nail conditions, and that review was about biotin taken by mouth, not on the scalp.

The formula is alcohol-based and contains salicylic acid, menthol and fragrance, and Refilled says to use it up to 4 times a day. That is a lot of exposure for a sensitive scalp or hairline, so patch test first.

If you have thinning hair, a dermatologist can check for causes and discuss treatments with stronger evidence. Minoxidil is the over-the-counter hair-loss treatment the FDA has approved for women.', 'On Amazon it has 4.6 out of 5 stars from 29 ratings; 72% are five stars and none are one or two stars. All of the reviews shown on the page are Amazon Vine reviews of a free product. Reviewers mostly mention the cooling feel, the easy roller and less itching; a few say they see a little new growth after a few weeks, and others haven''t noticed a change in density yet. ayna did not capture review numbers from Ulta.', 'No published study of this serum or of cADPR for hair was found. Refilled''s results come from unpublished testing with no details on size or design.', 'brand', 'Product claims are sourced from Refilled; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Amazon":"https://www.amazon.com/dp/B0GMRT3ZLD","Ulta":"https://www.ulta.com/p/hair-recovery-cytokine-effector-plus-pimprod2057765"},"ingredients":"Full ingredient list per Ulta: Water, Alcohol Denat., Glycerin, Dipropylene Glycol, Butylene Glycol, Lecithin, Dioscorea Japonica Root Extract, Viola Mandshurica Flower Extract, Aloe Barbadensis Leaf Extract, Ulmus Davidiana Root Extract, Laminaria Japonica Extract, Menthol, 1,2-Hexanediol, Salicylic Acid, Panthenol, Fragrance, Arginine, Caprylyl Glycol, Polysorbate 20, Caprylic/Capric Triglyceride, Nicotinic Acid Adenine Dinucleotide Phosphate, Xylitol, Cannabis Sativa Seed Oil, Houttuynia Cordata Extract, Ginkgo Biloba Leaf Extract, Citrus Limon (Lemon) Fruit Extract, Chamaecyparis Obtusa Leaf Extract, Bambusa Vulgaris Extract, Pinus Densiflora Leaf Extract, Thuja Orientalis Extract, Glycine, Propolis Extract, Citrus Nobilis (Mandarin Orange) Oil, Serine, Glutamic Acid, Glutathione, Zingiber Officinale (Ginger) Root Oil, Cyclic Adenosine Diphosphate Ribose, Aspartic Acid, Leucine, Polyglyceryl-4 Caprate, Alanine, Lysine, Tyrosine, Phenylalanine, Proline, Threonine, Valine, Isoleucine, Histidine, Cysteine, Methionine, Niacinamide, Biotin, Inositol, Sodium Ascorbyl Phosphate, Tocopherol, Limonene, Linalool. Amazon lists the ingredients only as \"cADPR. NAD+. Salicylic Acid. Biotin. Cytokine.\" The full list has no ingredient named cytokine and no NAD+ (it has a related compound, nicotinic acid adenine dinucleotide phosphate).","doctorOpinionShort":"Refilled''s results come from unpublished testing with no details. Its headline ingredient, cADPR, has no published hair research ayna could find, and the \"cytokine\" and \"NAD+\" on Amazon aren''t named in the full ingredient list. Alcohol-based with salicylic acid, menthol and fragrance.","doctorOpinionCitations":[{"url":"https://www.ulta.com/p/hair-recovery-cytokine-effector-plus-pimprod2057765","label":"Ulta: Refilled Hair Recovery Cytokine Effector Plus, ingredients, claims and directions"},{"url":"https://www.amazon.com/dp/B0GMRT3ZLD","label":"Amazon: Refilled cADPR Effector Plus, listing and safety information"},{"url":"https://pubmed.ncbi.nlm.nih.gov/28879195/","label":"PubMed: A review of the use of biotin for hair loss (Skin Appendage Disord 2017)","chipLabel":"Biotin review (2017)"},{"url":"https://www.accessdata.fda.gov/scripts/cder/daf/index.cfm?event=overview.process&ApplNo=021812","label":"FDA (Drugs@FDA): NDA 021812, Women''s Rogaine 5% minoxidil foam, over-the-counter","chipLabel":"FDA: minoxidil for women"}],"whoItsFor":["People who want a small, cooling roll-on for a thinning hairline, part or crown and are comfortable with brand-only evidence","Not ideal for a sensitive scalp: it contains alcohol, salicylic acid, menthol and fragrance","Not a substitute for seeing a dermatologist about new, sudden or patchy hair loss"],"howToUse":{"intro":"Per Refilled (Ulta listing): use 2 to 4 times a day, about every 3 to 4 hours, day or evening.","steps":["Apply directly to thinning areas: hairline, crown, part line or eyebrows.","Gently massage into the scalp with your fingertips in circular motions.","Let it absorb fully. No rinsing needed."],"sourceUrl":"https://www.ulta.com/p/hair-recovery-cytokine-effector-plus-pimprod2057765","sourceLabel":"Ulta: Refilled Hair Recovery Cytokine Effector Plus"},"warnings":["External use only. Rinse right away if it gets in your eyes (per Refilled).","Stop using it if you get a rash or irritation, including with sun exposure, and see a doctor if it continues (per Refilled).","Don''t apply on wounds, damaged or broken skin (per Refilled).","Contains alcohol, salicylic acid, menthol and fragrance: patch test first if you have a sensitive scalp.","Keep away from children under 3 (per Refilled)."],"ingredientScience":[{"name":"cADPR (cyclic adenosine diphosphate ribose)","text":"Refilled calls this patented Korean scalp technology that supports healthier-looking hair and stronger-looking roots. A PubMed search for cyclic ADP-ribose and hair returned one study, about hair cells in the inner ear, not scalp hair. ayna found no published research on it for hair loss.","citations":[{"url":"https://www.ulta.com/p/hair-recovery-cytokine-effector-plus-pimprod2057765","label":"Ulta: Refilled Effector Plus, ingredient claims"}]},{"name":"Biotin","text":"Refilled says biotin helps hair look thicker and fuller. A 2017 review of biotin for hair and nails found 18 reported cases where it helped, all in people with an underlying problem such as biotin deficiency, and concluded there isn''t enough evidence to support it in healthy people. The review covered biotin taken by mouth, not applied to the scalp.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28879195/","label":"PubMed: A review of the use of biotin for hair loss (Patel et al., Skin Appendage Disord 2017)"}]}],"scientificCitations":[{"url":"https://www.aad.org/public/diseases/hair-loss/types/female-pattern","text":"American Academy of Dermatology: Female pattern hair loss","summary":"The AAD says the FDA has approved 2% and 5% minoxidil as a non-prescription treatment for female pattern hair loss and calls it the most-recommended treatment. This is general guidance, not product-specific validation."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"amazon","url":"https://www.amazon.com/dp/B0GMRT3ZLD","text":"Amazon: Refilled cADPR Effector Plus reviews","summary":"4.6 out of 5 stars from 29 ratings as of October 2026; the reviews shown are Vine reviews of a free product."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb)
